---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class GuideTaskInfo : IDataInfo
local GuideTaskInfo = class("GuideTaskInfo", IDataInfo)
---@type TaskMgr
local TaskMgr = T(Global, "TaskMgr")
---@type GuideTaskGroupConfig
local GuideTaskGroupConfig = T(Global, "GuideTaskGroupConfig")
---@type TaskGroupConfig
local TaskGroupConfig = T(Global, "TaskGroupConfig")
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")

local function getDailyTaskTag()
    return math.floor(os.time() / DateUtil.getDaySeconds()) + 1
end

function GuideTaskInfo:onCreate()
    self.curGuideKey = Define.TaskGroup.TaskGuideV2
    ---key, defValue, toSelf, toOther, saveDB
    self:initKey(Define.GuideTaskInfoKey.TaskRefreshTag, 0, true, false, true)
    self:initKey(Define.GuideTaskInfoKey.TaskRefreshTime, 0, true, false, true)
    self:initKey(Define.GuideTaskInfoKey.DailyTaskIds, {}, true, false, true)
    self:initKey(Define.GuideTaskInfoKey.TaskGroupReward, {}, true, false, true)
end

---@param player SBasePlayer | CBasePlayer
function GuideTaskInfo:initPlayer(player)
    self.player = player
end

function GuideTaskInfo:onPlayerReady()
    if isClient then
        for _, key in pairs(Define.TaskGuideKey) do
            self.player.task:addInitObserver(key, function(_, group)
                if group then
                    self.curGuideKey = key
                    group:addObserver(function(_, task)
                        if task:isTaskFinish() then
                            Events.FuncUnlockChangeEvent:invoke()
                        end
                    end)
                end
                Events.FuncUnlockChangeEvent:invoke()
            end)
        end
    else
        for _, key in pairs(Define.TaskGuideKey) do
            self.player.task:addInitObserver(key, function(_, group)
                if not group then
                    return
                end
                self.curGuideKey = key
                self.player.info:onReportLogin(self.player, key)
                group:addObserver(function(_, task)
                    if task.status == Define.TaskStatus.Received then
                        local unlock = GuideTaskGroupConfig:getCfgByKeyAndNumber(task.group.key, task.times)
                        if unlock and unlock.unlockKey then
                            self.player.task:initTaskGroup(unlock.unlockKey)
                        end
                    end
                    ---主线任务做完，自动领取每日任务
                    self:tryUpdateDailyTask()
                end)
            end)
        end

        ---@param task TaskLink
        self.observer = function(_, task)
            local taskIds = self:getValue(Define.GuideTaskInfoKey.DailyTaskIds)
            local times = tostring(task.times)
            local taskId = taskIds[times]
            if taskId ~= task.taskId then
                taskIds[times] = task.taskId
                self:setValue(Define.GuideTaskInfoKey.DailyTaskIds, taskIds)
            end
        end
        local daily = self.player.task:getTaskGroup(Define.TaskGroup.TaskDaily)
        if daily then
            daily:addObserver(self.observer)
        end
    end
end

function GuideTaskInfo:initTaskGuideGroup()
    if self.player.info:isVersionNewPlayer() then
        for _, key in pairs(Define.TaskGuideKey) do
            local group = self.player.task:getTaskGroup(key)
            if group and next(group.tasks) ~= nil then
                return
            end
        end
        local number = self.player.userId % 100
        local group
        if number <= 10 then
            group = Define.TaskGroup.TaskGuideV2
        elseif number <= 30 then
            group = Define.TaskGroup.TaskGuideV7
        elseif number <= 70 then
            group = Define.TaskGroup.TaskGuideV6
        else
            group = Define.TaskGroup.TaskGuideV4
        end
        local cfgs = TaskGroupConfig:getCfgsByKey(group)
        if not next(cfgs) then
            group = Define.TaskGroup.TaskGuideV2
        end
        self.player.task:initTaskGroup(group)
        if self.player.guide_task:isFuncUnlock("island") then
            self.player:checkBackHome()
        end
    else
        ---初始化老玩家任务，并且设置完成状态
        local keys = GuideTaskGroupConfig:getGuideTaskAllKeys()
        local ignores = {
            [Define.TaskGroup.TaskGuideV3] = true,
            [Define.TaskGroup.TaskGuideV4] = true,
            [Define.TaskGroup.TaskGuideV5] = true,
            [Define.TaskGroup.TaskGuideV6] = true,
            [Define.TaskGroup.TaskGuideV7] = true,
        }
        for _, key in pairs(keys) do
            if ignores[key] then
                goto CONTINUE
            end
            local group = self.player.task:getTaskGroup(key)
            if not group or next(group.tasks) == nil then
                group = self.player.task:initTaskGroup(key)
            end
            while not group:isAllTaskEnd() do
                for _, task in pairs(group.tasks) do
                    task:tryRandomTask(true)
                    task.status = Define.TaskStatus.Received
                end
            end
            :: CONTINUE ::
        end
    end
end

function GuideTaskInfo:onTick()
    if isClient then
        return
    end
    if not self.player:checkReady() then
        return
    end
    self:tryUpdateDailyTask()
end

function GuideTaskInfo:getTaskGuideGroup()
    return self.player.task:getTaskGroup(self.curGuideKey)
end

---获取当前矿区的任务(引导或每日由UI判定)
---@return TaskGroup | nil
function GuideTaskInfo:getGuideTask()
    local guide = self.player.task:getTaskGroup(self.curGuideKey)
    if not guide then
        return nil
    end
    if guide:isAllTaskEnd() then
        return self.player.task:getTaskGroup(Define.TaskGroup.TaskDaily)
    else
        return guide
    end
end

---@private
function GuideTaskInfo:tryUpdateDailyTask()
    local guide = self.player.task:getTaskGroup(self.curGuideKey)
    if not guide then
        return
    end
    if not guide:isAllTaskEnd() then
        return
    end
    local daily = self.player.task:getTaskGroup(Define.TaskGroup.TaskDaily)
    if not daily then
        daily = self.player.task:initTaskGroup(Define.TaskGroup.TaskDaily)
        daily:addObserver(self.observer)
        self:resetDailyTaskReward()
        self:setValue(Define.GuideTaskInfoKey.DailyTaskIds, { ["1"] = daily.tasks[1].taskId })
        TaskMgr:trySyncTask(self.player)
    else
        if not self.observation then
            self.observation = true
            daily:addObserver(self.observer)
        end
        local tag1 = self:getValue(Define.GuideTaskInfoKey.TaskRefreshTag)
        local tag2 = getDailyTaskTag()
        if tag1 < tag2 then
            ---更新每日任务
            daily:resetTaskGroup()
            self:resetDailyTaskReward()
            self:setValue(Define.GuideTaskInfoKey.DailyTaskIds, { ["1"] = daily.tasks[1].taskId })
            self:setValue(Define.GuideTaskInfoKey.TaskRefreshTag, tag2)
            self:setValue(Define.GuideTaskInfoKey.TaskRefreshTime, tag2 * DateUtil.getDaySeconds())
        end
    end
end

function GuideTaskInfo:resetDailyTaskReward()
    local rewards = self:getValue(Define.GuideTaskInfoKey.TaskGroupReward)
    local cfgs = GuideTaskGroupConfig:getAllCfgs()
    local need = false
    for _, cfg in pairs(cfgs) do
        if cfg.key == Define.TaskGroup.TaskDaily and rewards[tostring(cfg.group)] then
            rewards[tostring(cfg.group)] = nil
            need = true
        end
    end
    if need then
        self:setValue(Define.GuideTaskInfoKey.TaskGroupReward, rewards)
    end
end

---获取每日任务下次刷新时间
function GuideTaskInfo:getTaskRefreshTime()
    return self:getValue(Define.GuideTaskInfoKey.TaskRefreshTime)
end

function GuideTaskInfo:isGuideTaskEnd()
    local guide = self:getTaskGuideGroup()
    if not guide then
        return false
    end
    return guide:isAllTaskEnd()
end

function GuideTaskInfo:isAllTaskEnd()
    for _, key in pairs(GuideTaskGroupConfig:getGuideTaskAllKeys()) do
        local group
        if Define.TaskGuideKey[key] then
            group = self:getTaskGuideGroup()
        else
            group = self.player.task:getTaskGroup(key)
        end
        if not group or not group:isAllTaskEnd() then
            return false
        end
    end
    local daily = self.player.task:getTaskGroup(Define.TaskGroup.TaskDaily)
    if not daily then
        return false
    end
    return daily:isAllTaskEnd()
end

---@return table<string, TaskGroup>
function GuideTaskInfo:getTaskGroupByGroup(groupId)
    local groups = {}
    local keys = GuideTaskGroupConfig:getGroupKeys(groupId)
    for _, key in pairs(keys) do
        local group = self.player.task:getTaskGroup(key)
        if group then
            groups[key] = group
        end
    end
    return groups
end

function GuideTaskInfo:getGuideTimes(ignoreDoing)
    local times = 0
    for _, key in pairs(GuideTaskGroupConfig:getGuideTaskAllKeys()) do
        local group = self.player.task:getTaskGroup(key)
        local task = group and group.tasks[1]
        if task then
            if not ignoreDoing then
                times = times + task.times
            else
                times = times + (task:isTaskFinish() and task.times or task.times - 1)
            end
        end
    end
    return times
end

function GuideTaskInfo:isTaskGroupRewardReceived(groupId)
    local rewards = self:getValue(Define.GuideTaskInfoKey.TaskGroupReward)
    return rewards[tostring(groupId)]
end

function GuideTaskInfo:isFuncUnlock(name)
    local times = GuideTaskGroupConfig:getUnlockFuncCfg(self.curGuideKey, name)
    if not times then
        return true
    end
    local guide = self.player.task:getTaskGroup(self.curGuideKey)
    local task = guide and guide.tasks[1]
    if not task then
        return false
    end
    if task:isTaskFinish() then
        return task.times >= times
    else
        return task.times > times
    end
end

function GuideTaskInfo:haveGuideTaskReward()
    local cfgs = {}
    if self:getTaskGuideGroup() then
        for _, cfg in pairs(GuideTaskGroupConfig:getAllCfgs(self.curGuideKey)) do
            if cfg.key == self.curGuideKey then
                table.insert(cfgs, cfg)
            end
        end
    end
    table.sort(cfgs, function(a, b)
        return a.group < b.group
    end)
    local haveReward = false
    local rewardIndex = 0
    for index, cfg in pairs(cfgs) do
        local number = 0
        local totalNumber = #cfg.tasks
        for _, item in pairs(cfg.tasks) do
            local group = self.player.task:getTaskGroup(item.key)
            local task = group and group.tasks[1]
            if task then
                if item.number < task.times then
                    number = number + 1
                elseif item.number == task.times then
                    if task:isTaskFinish() then
                        number = number + 1
                        if task:isHaveReceived() then
                            rewardIndex = index
                            haveReward = true
                            break
                        end
                    end
                end
            end
        end
        if not haveReward then
            if number >= totalNumber and not self:isTaskGroupRewardReceived(cfg.group) then
                haveReward = true
                rewardIndex = index
                break
            end
        else
            break
        end
    end
    return haveReward, rewardIndex
end

return GuideTaskInfo
